const rows = $input.all();

const senderId = $('IDS AND TEXT').first().json.sender_id;
const currentMessage = $('IDS AND TEXT').first().json.message_text;

// Retrieve valid conversation messages for this customer.
const history = rows
  .map(item => item.json)
  .filter(row =>
    String(row.sender_id || '') === String(senderId) &&
    ['user', 'assistant'].includes(row.role) &&
    String(row.message || '').trim() !== ''
  )
  // Keep only the last 10 messages.
  .slice(-10)
  .map(row => ({
    role: row.role,
    content: String(row.message)
  }));

return [{
  json: {
    sender_id: senderId,
    current_message: currentMessage,
    chat_history: history,
    history_count: history.length
  }
}];

const memory = $('Format Chat History').first().json;
const rows = $input.all();

const approvedProjects = rows
  .map(item => item.json)
  .filter(project =>
    String(project['status(For F-7)'] || '').trim().toLowerCase() === 'approved'
  )
  .map(project => ({
    project_id: project.project_id || '',
    project_name: project.project_name || '',
    category: project.category || '',
    description: project.description || '',
    technologies_used: project.technologies_used || '',
    price: project.price || '',
    instagram_video: project.instagram_video || ''
  }));

return [{
  json: {
    sender_id: memory.sender_id,
    current_message: memory.current_message,
    chat_history: memory.chat_history || [],
    approved_projects: approvedProjects,
    project_count: approvedProjects.length
  }
}];

