const rules = $('IG - Get Comment Rules')
  .all()
  .map(item => item.json);

// Read Instagram media from ALL paginated output items
const mediaItems = $('IG - Fetch Published Media')
  .all()
  .flatMap(item => {
    const data = item.json.data;

    return Array.isArray(data) ? data : [];
  });

function getShortcode(url) {
  const match = String(url || '').match(
    /instagram\.com\/(?:p|reel|tv)\/([^/?#]+)/
  );

  return match ? match[1] : null;
}

const results = [];

for (const rule of rules) {
  const shortcode = getShortcode(rule.post_url);

  const matchedPost = mediaItems.find(
    post => getShortcode(post.permalink) === shortcode
  );

  if (shortcode && matchedPost) {
    results.push({
      json: {
        ...rule,
        media_id: matchedPost.id,
        mapping_status: 'matched'
      }
    });
  }
}

return results;

const comment = $('IG - Extract Comment Data').first().json;

const rules = $input.all().map(item => item.json);

const mediaExists = rules.some(rule =>
  String(rule.media_id || '').trim() ===
  String(comment.media_id || '').trim()
);

return [{
  json: {
    media_id: comment.media_id,
    media_exists: mediaExists
  }
}];

const comment = $('IG - Extract Comment Data').first().json;

// Read all rules from Google Sheets
const rules = $('IG - Get Comment Rules')
  .all()
  .map(item => item.json);

// Read current branch data
const incoming = $input.all().map(item => item.json);

// Include newly mapped rules
const updatedRules = incoming.filter(item =>
  item.media_id && item.keyword
);

const allRules = [...updatedRules, ...rules];

// Find matching media ID, keyword, and active status
const matchedRule = allRules.find(rule =>
  String(rule.media_id || '').trim() ===
    String(comment.media_id || '').trim() &&

  String(rule.keyword || '').trim().toLowerCase() ===
    String(comment.comment_text || '').trim().toLowerCase() &&

  String(rule.status || '').trim().toLowerCase() === 'active'
);

// Return matched: false when no rule matches
if (!matchedRule) {
  return [{
    json: {
      ...comment,
      matched: false,
      reason: "No matching active comment rule"
    }
  }];
}

// Return matched: true when a rule matches
return [{
  json: {
    ...comment,
    keyword: matchedRule.keyword,
    public_reply: matchedRule.public_reply,
    private_dm: matchedRule.private_dm,
    matched: true
  }
}];

