const results = [];

for (const item of $input.all()) {
  let raw = item.json.text ?? item.json.output;

  // Convert AI output into JSON
  if (typeof raw === 'string') {
    raw = raw.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    raw = JSON.parse(raw);
  }

  // Validate response structure
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Invalid AI response format');
  }

  // Extract mode
  const mode = String(raw.mode || '').toUpperCase();

  if (!['AI', 'HUMAN'].includes(mode)) {
    throw new Error('Invalid AI response mode');
  }

  // Extract customer reply
  if (typeof raw.reply !== 'string' || !raw.reply.trim()) {
    throw new Error('Missing AI reply');
  }

  const reply = raw.reply.trim();

  // Extract conversation summary
  const summary =
    typeof raw.summary === 'string'
      ? raw.summary.trim()
      : '';

  // HUMAN requests must have a summary
  if (mode === 'HUMAN' && !summary) {
    throw new Error('Missing human assistance summary');
  }

  results.push({
    json: {
      mode,
      reply,
      summary: mode === 'HUMAN' ? summary : ''
    }
  });
}

return results;

const context = $('IG - Prepare AI Context').first().json;
const aiResponse = $('IG - Parse AI Response').first().json;

// 1. Get current Instagram sender ID
const senderId = String(context.sender_id || '').trim();

if (!senderId) {
  throw new Error('Missing Instagram Sender ID');
}

// 2. Verify HUMAN request
if (String(aiResponse.mode).toUpperCase() !== 'HUMAN') {
  throw new Error('Human assistance was not requested');
}

// 3. Get all rows from Human_Handoff sheet
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.sender_id && row.request_id);

// 4. FIRST: Check whether sender ID already exists
const existing = rows.find(row =>
  String(row.sender_id).trim() === senderId
);

let requestId;

// 5. Existing sender: reuse same Request ID
if (existing) {
  requestId = String(existing.request_id).trim();
}

// 6. New sender: generate next Request ID
else {
  const numbers = rows.map(row => {
    const match = String(row.request_id || '')
      .trim()
      .match(/^HR-(\d+)$/);

    return match ? Number(match[1]) : 0;
  });

  const highestNumber = Math.max(0, ...numbers);
  const nextNumber = highestNumber + 1;

  requestId = `HR-${String(nextNumber).padStart(3, '0')}`;
}

// 7. Get AI-generated conversation summary
const summary = String(aiResponse.summary || '').trim();

if (!summary) {
  throw new Error('Missing AI-generated conversation summary');
}

// 8. Get customer's latest message
const reason = String(context.current_message || '').trim();

// 9. Generate Pakistan timestamp
const timestamp = $now
  .setZone('Asia/Karachi')
  .toFormat('yyyy-MM-dd HH:mm:ss');

// 10. Preserve original request date for existing sender
const requestedAt = existing?.requested_at || timestamp;

// 11. Return exactly ONE item
return [{
  json: {
    request_id: requestId,
    sender_id: senderId,
    mode: 'human',
    handoff_status: 'pending',
    reason: reason,
    conversation_summary: summary,
    requested_at: requestedAt,
    updated_at: timestamp
  }
}];

const rows = $input.all()
  .map(item => item.json)
  .filter(row =>
    String(row.mode || '').trim().toLowerCase() === 'human'
  );

if (rows.length === 0) {
  return [{
    json: {
      message: 'No active human assistance requests.'
    }
  }];
}

return rows.map(row => {
  const requestId = String(row.request_id || '');
  const status = String(
    row.handoff_status || 'pending'
  ).trim().toLowerCase();

  const summary = String(
    row.conversation_summary || 'No summary available.'
  );

  let message;

  if (status === 'accepted') {
    message = [
      'HUMAN ASSISTANCE — ACCEPTED',
      '',
      `Request ID: ${requestId}`,
      '',
      'Human assistance accepted, but the chat has not been closed yet.',
      '',
      `Summary: ${summary}`,
      '',
      'To close:',
      `${requestId}: CHAT CLOSED`
    ].join('\n');
  } else {
    message = [
      'HUMAN ASSISTANCE — PENDING',
      '',
      `Request ID: ${requestId}`,
      '',
      `Summary: ${summary}`,
      '',
      'Reply with:',
      `${requestId}: ACCEPTED`,
      `${requestId}: DECLINED`
    ].join('\n');
  }

  return {
    json: {
      request_id: requestId,
      handoff_status: status,
      message
    }
  };
});

