const developerMessage = String(
  $('IG - Is Developer Account?').first().json
    .body?.entry?.[0]?.messaging?.[0]?.message?.text || ''
).trim();

const lines = developerMessage.split(/\r?\n/);

const results = [];

for (const line of lines) {
  const match = line.trim().match(
    /^(HR-\d+)\s*:\s*(ACCEPTED|DECLINED|CHAT\s*CLOSED)$/i
  );

  if (!match) continue;

  const requestId = match[1].toUpperCase();

  const action = match[2]
    .replace(/\s+/g, '')
    .toUpperCase();

  let mode;
  let handoffStatus;

  if (action === 'ACCEPTED') {
    mode = 'human';
    handoffStatus = 'accepted';

  } else if (action === 'DECLINED') {
    mode = 'ai';
    handoffStatus = 'declined';

  } else if (action === 'CHATCLOSED') {
    mode = 'ai';
    handoffStatus = 'closed';

  } else {
    continue;
  }

  results.push({
    json: {
      valid: true,
      request_id: requestId,
      action: action === 'CHATCLOSED'
        ? 'CHAT CLOSED'
        : action,
      mode: mode,
      handoff_status: handoffStatus
    }
  });
}

if (results.length === 0) {
  return [{
    json: {
      valid: false,
      message: 'No valid developer commands found.'
    }
  }];
}

return results;

const rows = $input.all();

const messages = {
  accepted: 'Human assistance accepted. AI replies remain paused.',
  declined: 'Human assistance declined. AI replies are enabled.',
  closed: 'Human chat closed. AI mode is re-enabled.'
};

const confirmations = rows.map(item => {
  const row = item.json;

  const requestId = String(row.request_id || '').trim();

  const rawStatus = String(row.handoff_status || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '');

  const status = rawStatus === 'chatclosed'
    ? 'closed'
    : rawStatus;

  const lines = [
    `Request ID: ${requestId}`,
    `Status: ${status.toUpperCase()}`,
    messages[status] || 'Handoff status updated.'
  ];

  if (status === 'accepted') {
    lines.push(
      `To close the chat, type: ${requestId}: CHAT CLOSED`
    );
  }

  return lines.join('\n');
});

return [{
  json: {
    message: confirmations.join('\n\n----------------\n\n'),
    total_confirmations: confirmations.length
  }
}];

